import { SDKRequestToRESTRequestRenameMap } from './constants.js';
export const systemFieldRenameMap = SDKRequestToRESTRequestRenameMap;
export function renameFieldPathBySegment(fieldPath, renameMap) {
    return fieldPath
        ?.split('.')
        .map((segment) => renameMap?.[segment] ?? segment)
        .join('.');
}
